(function initLogo() {
  const path = document.getElementById("afterdosePath");
  if (path) path.setAttribute("d", LOGO_D);
})();

/* ==========================================================
   ВСТУПИТЕЛЬНЫЙ ЭКРАН (splash), в три фазы:
   1. контур логотипа "рисуется от руки" — отдельными мазками
      друг за другом (как в рукописной подписи), а не одной линией
   2. мазки растворяются, проступает золотая заливка
   3. логотип уменьшается и уплывает наверх — на его месте,
      в шапке, проявляется вся страница
   "???" — заглушка, потом здесь появится подпись.
   ========================================================== */

(function runSplash() {
  const splash = document.getElementById("splash");
  const wrap = document.getElementById("wrap");
  const logoWrap = document.getElementById("splashLogoWrap");
  const strokeLayer = document.getElementById("strokeLayer");
  const splashSub = document.getElementById("splash-sub");
  if (!splash || !wrap || !logoWrap || !strokeLayer) return;

  const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  if (reducedMotion) {
    splash.remove();
    wrap.classList.add("visible");
    return;
  }

  // тайминги (мс)
  const DRAW_MS = 2000; // на сколько растянута рисовка ВСЕХ мазков вместе
  const FILL_MS = 550;  // растворение мазков / проступание заливки
  const HOLD_MS = 500;  // логотип стоит уже залитый, перед тем как уплыть
  const FLY_MS = 850;   // "полёт" наверх

  document.body.classList.add("no-scroll");

  // делим общий контур на отдельные мазки (подпути) — каждый рисуется
  // своим куском общего времени DRAW_MS, пропорционально своей длине,
  // один за другим, как при рукописном написании
  const svgNS = "http://www.w3.org/2000/svg";
  const subDs = LOGO_D.match(/M [^M]*/g) || [];

  const strokeEls = subDs.map((d) => {
    const p = document.createElementNS(svgNS, "path");
    p.setAttribute("d", d.trim());
    p.setAttribute("class", "sig-stroke");
    strokeLayer.appendChild(p);
    return p;
  });

  const lengths = strokeEls.map((p) => p.getTotalLength());
  const total = lengths.reduce((a, b) => a + b, 0) || 1;

  let elapsed = 0;
  strokeEls.forEach((p, i) => {
    const len = lengths[i];
    const dur = (len / total) * DRAW_MS;
    const delay = elapsed;
    elapsed += dur;
    p.style.strokeDasharray = String(len);
    p.style.strokeDashoffset = String(len);
    p.getBoundingClientRect(); // форсируем layout перед тем как назначить transition
    p.style.transition = `stroke-dashoffset ${dur}ms cubic-bezier(.65,0,.35,1) ${delay}ms`;
  });

  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      strokeEls.forEach((p) => { p.style.strokeDashoffset = "0"; });
    });
  });

  // фаза 2: заливка проступает, мазки растворяются
  setTimeout(() => {
    logoWrap.classList.add("filled");
    if (splashSub) splashSub.classList.add("visible");
  }, DRAW_MS + 20);

  // фаза 3: логотип уплывает наверх, страница проявляется
  setTimeout(() => {
    splash.classList.add("leaving");
    wrap.classList.add("visible");
  }, DRAW_MS + 20 + FILL_MS + HOLD_MS);

  setTimeout(() => {
    splash.remove();
    document.body.classList.remove("no-scroll");
  }, DRAW_MS + 20 + FILL_MS + HOLD_MS + FLY_MS);
})();
